package hk.local.enginex7;
import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.media.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
import java.lang.ref.WeakReference;

public final class EngineService extends Service {
 public static volatile EngineService instance;public Config config;public EngineModel model;public AudioOutput audio;public DrivingInput input;public VehicleInput vehicle;public volatile boolean pendingStart,minimized,testing;public volatile String message="";public volatile long ticks;
 public interface Host {void floating();void minimize();void exit();void permission();}
 private final IBinder binder=new LocalBinder();public class LocalBinder extends Binder {public EngineService get(){return EngineService.this;}}
 private final Handler handler=new Handler(Looper.getMainLooper());private WindowManager windows;View overlay;private AudioManager manager;private AudioFocusRequest focus;private PowerManager.WakeLock wake;private long last;private volatile boolean destroying;private HandlerThread physicsThread;private Handler physics;public boolean hasOverlay(){return overlay!=null;}
 private final Runnable tick=new Runnable(){public void run(){synchronized(EngineService.this){if(destroying)return;long now=SystemClock.elapsedRealtime();double dt=last==0?.02:(now-last)/1000.;last=now;
  if(pendingStart&&audio.ready){pendingStart=false;model.start();if(config.mode.equals("gps"))input.start();wake.acquire();updateNotification();}
  if(testing&&!audio.active()){testing=false;releaseWake();abandonFocus();}
  if((pendingStart||model.running)&&!audio.active()&&!audio.error.isEmpty()){pendingStart=false;model.stop();input.stop();releaseWake();message=audio.error;abandonFocus();updateNotification();}
  model.intensity=config.intensity/100.;model.compensation=config.latency/1000.;if(config.mode.equals("vehicle"))model.stepVehicle(dt,vehicle.snapshot,now);else model.step(dt,input.speed(),input.acceleration(),input.fresh());ticks++;physics.postDelayed(this,20);}}};
 @Override public void onCreate(){super.onCreate();instance=this;config=new Config(this);config.theme=getSharedPreferences("engine",0).getInt("theme",0);model=new EngineModel();model.select(Profile.get(config.profileId));model.setMode("sim".equals(config.mode));input=new DrivingInput(this);audio=new AudioOutput(this,config,model);manager=(AudioManager)getSystemService(AUDIO_SERVICE);windows=(WindowManager)getSystemService(WINDOW_SERVICE);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"7XEngine:running");wake.setReferenceCounted(false);
  vehicle=new VehicleInput(this);vehicle.start();config.save();NotificationChannel channel=new NotificationChannel("engine","7X Engine",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(channel);startForeground(7,notification());physicsThread=new HandlerThread("7X-engine-model",android.os.Process.THREAD_PRIORITY_DISPLAY);physicsThread.start();physics=new Handler(physicsThread.getLooper());physics.post(tick);
 }
 @Override public IBinder onBind(Intent intent){return binder;}
 @Override public int onStartCommand(Intent i,int flags,int id){String a=i==null?"":i.getAction();if("exit".equals(a)){exit();return START_NOT_STICKY;}if("stop".equals(a))stopEngine();if("restore".equals(a)){if(Settings.canDrawOverlays(this))showOverlay(false);else startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}return START_NOT_STICKY;}
 public synchronized void startEngine(){if(model.running||pendingStart||testing)return;message="";if(config.mode.equals("gps")&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){message=config.t("GPS 模式需精確定位；ECARX 模式毋須 GPS。","GPS mode needs location; ECARX mode does not.");return;}
  if(audio.active()){message=config.t("聲音正在停止，請稍候再啟動。","Audio is stopping. Please start again shortly.");return;}
  String problem=audio.canStart();if(!problem.isEmpty()){message=problem;return;}
  focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS){stopEngine();message=config.t("聲音焦點已轉交其他 App；按啟動繼續。","Audio focus moved to another app. Start to resume.");}else audio.focusScale=change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK?.2:change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT?0:1;},handler).build();
  if(manager.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){message=config.t("其他 App 正使用音訊，暫未能啟動。","Audio focus is unavailable.");abandonFocus();return;}audio.focusScale=1;
  if(audio.start()){pendingStart=true;updateNotification();}else{message=audio.error;abandonFocus();}
 }
 public synchronized void stopEngine(){pendingStart=testing=false;model.stop();input.stop();releaseWake();abandonFocus();handler.postDelayed(()->{if(!model.running&&!pendingStart&&!testing)audio.stop();},180);updateNotification();}
 public synchronized void testSpeaker(String output){if(model.running||pendingStart||audio.active()){message=config.t("請先熄匙，再按喇叭試音。","Stop the engine before the speaker test.");return;}message="";
  focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS)stopEngine();else audio.focusScale=change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT?0:change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK?.2:1;},handler).build();
  if(manager.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){message=config.t("未取得音訊焦點，請停止其他音訊後重試。","Audio focus unavailable. Stop other playback and retry.");abandonFocus();return;}audio.focusScale=1;
  if(audio.startTest(output)){testing=true;wake.acquire();}else{message=audio.error;abandonFocus();}
 }
 public synchronized void stopTest(){if(!testing&&!audio.testActive)return;testing=false;audio.stop();releaseWake();abandonFocus();}
 private void abandonFocus(){if(focus!=null){manager.abandonAudioFocusRequest(focus);focus=null;}}
 private void releaseWake(){if(wake!=null&&wake.isHeld())wake.release();}
 public synchronized void mode(String mode){if(model.running||pendingStart||testing)return;config.mode=mode;config.save();model.setMode("sim".equals(mode));message="";}
 public synchronized void select(String id){config.profileId=id;config.save();model.select(Profile.get(id));}
 public void showOverlay(boolean small){if(destroying)return;if(!Settings.canDrawOverlays(this)){message=config.t("請先授權顯示於其他 App 上層。","Allow display over other apps first.");return;}removeOverlay();minimized=small;
  WindowManager.LayoutParams lp=new WindowManager.LayoutParams();lp.type=WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY;lp.format=PixelFormat.TRANSLUCENT;lp.flags=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL;lp.gravity=Gravity.TOP|Gravity.RIGHT;lp.x=dp(12);lp.y=dp(28);
  Context themed=new android.view.ContextThemeWrapper(this,getResources().getIdentifier("AppTheme","style",getPackageName()));
  Host host=new Host(){public void floating(){showOverlay(false);}public void minimize(){showOverlay(true);}public synchronized void exit(){EngineService.this.exit();}public void permission(){startActivity(new Intent(EngineService.this,MainActivity.class).setAction("permission").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}};
  if(small){LinearLayout row=new LinearLayout(themed);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(4),dp(6),dp(4));row.setBackgroundColor(PanelView.SURFACE);Button restore=new Button(themed);restore.setText(config.t("7X · 還原","7X · Restore"));restore.setTextColor(PanelView.TEXT);restore.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,dp(16)*getResources().getConfiguration().fontScale);restore.setOnClickListener(v->showOverlay(false));row.addView(restore,new LinearLayout.LayoutParams(0,dp(56),1));Button close=new Button(themed);close.setText(config.t("退出","Exit"));close.setTextColor(PanelView.TEXT);close.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,dp(16)*getResources().getConfiguration().fontScale);close.setOnClickListener(v->exit());LinearLayout.LayoutParams closeParams=new LinearLayout.LayoutParams(dp(72),dp(56));closeParams.leftMargin=dp(8);row.addView(close,closeParams);overlay=row;lp.width=dp(272);lp.height=dp(68);}
  else{overlay=new PanelView(themed,this,host,true);lp.x=lp.y=0;lp.width=WindowManager.LayoutParams.MATCH_PARENT;lp.height=WindowManager.LayoutParams.MATCH_PARENT;}
  try{windows.addView(overlay,lp);}catch(Exception e){overlay=null;message=config.t("浮窗未能顯示：","Cannot display overlay: ")+e.getClass().getSimpleName();}
 }
 public void removeOverlay(){if(overlay!=null){try{windows.removeViewImmediate(overlay);}catch(Exception ignored){}overlay=null;}}
 public synchronized void exit(){destroying=true;pendingStart=false;model.stop();audio.stop();input.stop();vehicle.stop();removeOverlay();releaseWake();abandonFocus();handler.removeCallbacksAndMessages(null);if(physics!=null)physics.removeCallbacksAndMessages(null);if(physicsThread!=null)physicsThread.quitSafely();MainActivity a=MainActivity.current.get();if(a!=null)a.finishAndRemoveTask();stopForeground(true);stopSelf();}
 @Override public void onTaskRemoved(Intent root){super.onTaskRemoved(root);if(!destroying&&!hasOverlay()&&Settings.canDrawOverlays(this))showOverlay(true);}
 @Override public synchronized void onDestroy(){destroying=true;handler.removeCallbacksAndMessages(null);if(physics!=null)physics.removeCallbacksAndMessages(null);if(physicsThread!=null)physicsThread.quitSafely();if(model!=null)model.stop();if(audio!=null)audio.stop();if(input!=null)input.stop();if(vehicle!=null)vehicle.stop();removeOverlay();releaseWake();abandonFocus();instance=null;super.onDestroy();}
 private int dp(int n){android.util.DisplayMetrics m=new android.util.DisplayMetrics();windows.getDefaultDisplay().getMetrics(m);return Math.round(n*Math.max(m.density,Math.min(m.widthPixels/1024f,m.heightPixels/600f)));}
 private PendingIntent action(String a,int n){return PendingIntent.getService(this,n,new Intent(this,EngineService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(){String state=config.t("引擎待命","Engine ready");if(model.running||pendingStart)state=config.t("引擎運作中 · 可於背景繼續","Engine running · background playback");return new Notification.Builder(this,"engine").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("7X Engine").setContentText(state).setOngoing(true).setContentIntent(action("restore",1)).addAction(new Notification.Action.Builder(null,config.t("還原","Restore"),action("restore",1)).build()).addAction(new Notification.Action.Builder(null,config.t("熄匙","Stop"),action("stop",2)).build()).addAction(new Notification.Action.Builder(null,config.t("退出","Exit"),action("exit",3)).build()).build();}
 public void updateNotification(){if(!destroying)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7,notification());}
}
